/** Thai purpose for a chapter (architecture stores English purposes). */
function thPurpose(chapter: ChapterPlan): string {
  if (chapter.sceneType && TH_SCENE_PURPOSE[chapter.sceneType]) return TH_SCENE_PURPOSE[chapter.sceneType];
  if (chapter.type && TH_NF_PURPOSE[chapter.type]) return TH_NF_PURPOSE[chapter.type];
  return chapter.purpose;
}

function thTypeLabel(chapter: ChapterPlan): string {
  const t = chapter.type ?? chapter.sceneType ?? "section";
  return TH_TYPE_LABEL[t] ?? t;
}

function thAgentHeader(c: BookConfig): string {
  const lang = c.language === "thai" ? "ภาษาไทย" : c.language === "bilingual" ? "ไทย+อังกฤษ" : "อังกฤษ";
  return `โปรเจกต์: "${c.title}" — ${BOOK_TYPES[c.type].label} (${c.subGenre.replace(/_/g, " ")})\nแก่นเรื่อง: ${c.thesis}\nผู้อ่าน: ${c.reader} · เสียง: ${c.voice} · ภาษาผลลัพธ์: ${lang}`;
}

function thQualityStandards(type: BookTypeKey): string {
  const m: Record<string, string> = {
    novel: `- โชว์มากกว่าเล่า (แสดงผ่านการกระทำ/ประสาทสัมผัส)\n- มีรายละเอียดประสาทสัมผัสอย่างน้อย 2 อย่างต่อฉาก\n- จบทุกบทด้วย hook (คำถาม/การเปิดเผย/พลิกผัน)\n- เสียงตัวละครต่างกันชัด แยกออกได้จากบทพูด\n- ความตึงเครียดต้องไต่ระดับขึ้นทั้งเล่ม\n- ทุกฉากมี: ความขัดแย้ง + จุดพลิก + ผลลัพธ์`,
    nonfiction: `- ทุกข้ออ้างต้องมีหลักฐานรองรับ\n- ลำดับน้ำหนักหลักฐาน: meta-analysis > RCT > cohort > case > ผู้เชี่ยวชาญ > เรื่องเล่า\n- นิยามศัพท์เฉพาะเมื่อใช้ครั้งแรก\n- เชื่อมเหตุผลระหว่างย่อหน้าให้ชัด\n- มี objective + key takeaway + แบบฝึกหัด\n- ข้อโต้แย้งฝ่ายตรงข้าม: นำเสนออย่างเป็นธรรมแล้วโต้กลับ\n- พิสูจน์แก่นเรื่องให้ครบเมื่อจบเล่ม`,
    howto: `- ขั้นตอนครบ เรียงลำดับ ไม่มีช่องโหว่\n- ใครก็ทำตามได้ตั้งแต่ขั้นแรก\n- คำเตือนความปลอดภัยชัดเจน\n- รายการวัสดุ/อุปกรณ์ครบก่อนเริ่ม\n- มีส่วนแก้ปัญหาที่พบบ่อย`,
    kids: `- คำศัพท์เหมาะวัย\n- อ่านออกเสียงแล้วลื่น มีจังหวะ\n- มีการซ้ำคำ/คำคล้องเพื่อความสนุก\n- ข้อความเชิงบวก ไม่สั่งสอนตรง ๆ\n- มีโน้ตภาพประกอบทุกหน้า`,
    cookbook: `- รูปแบบสูตรเป็นมาตรฐาน\n- หน่วยวัด: เมตริก + อิมพีเรียล\n- ส่วนผสมเรียงตามลำดับการใช้\n- หนึ่งขั้นตอน = หนึ่งการกระทำ\n- ระบุเวลาเตรียม/ปรุง/รวม และจำนวนเสิร์ฟ`,
    textbook: `- ความถูกต้องของเนื้อหา\n- มี learning objective + แบบฝึกหัด + คำถามทบทวน\n- ความยากไล่ระดับ\n- มีตัวอย่างและการประยุกต์ใช้จริง`,
    memoir: `- ความจริงทางอารมณ์เหนือสิ่งอื่นใด\n- โชว์ช่วงเวลาสำคัญผ่านฉาก ไม่ใช่สรุป\n- เสียงเล่าจริงใจ เปราะบางได้แต่ไม่สงสารตัวเอง\n- รายละเอียดประสาทสัมผัสจากความทรงจำ\n- แก่นเรื่องร้อยทุกบท`,
    poetry: `- ภาพพจน์รูปธรรมและแปลกใหม่\n- เว้นบรรทัดอย่างตั้งใจ\n- ทุกคำมีความหมาย ประหยัดคำ\n- อ่านออกเสียงแล้วไพเราะ\n- จบด้วยความกังวานที่ค้างใจ`,
  };
  return m[type] ?? m.nonfiction;
}

function thChecklist(type: BookTypeKey): string {
  const m: Record<string, string> = {
    novel: `  □ โชว์มากกว่าเล่า\n  □ ประสาทสัมผัส ≥ 2 ต่อฉาก\n  □ บทพูดขับเคลื่อนเรื่องหรือเผยตัวละคร\n  □ จบบทด้วย hook\n  □ เสียงตัวละครต่างกันชัด\n  □ ไม่มีคำซ้ำซาก/สำนวนเฝือ\n  □ ความยาวใกล้เป้าหมาย (±20%)`,
    nonfiction: `  □ ทุกข้ออ้างมีหลักฐาน\n  □ นิยามศัพท์เฉพาะครั้งแรก\n  □ เหตุผลเชื่อมต่อกันชัด\n  □ มี objective/takeaway\n  □ น้ำเสียงสม่ำเสมอ\n  □ ความยาวใกล้เป้าหมาย (±20%)`,
    poetry: `  □ ภาพพจน์รูปธรรม\n  □ เว้นบรรทัดตั้งใจ\n  □ ทุกคำมีค่า\n  □ อ่านออกเสียงไพเราะ\n  □ จบกังวาน`,
  };
  return m[type] ?? `  □ ตรงตามวัตถุประสงค์ของบท\n  □ ลำดับ/เหตุผลชัด\n  □ น้ำเสียงสม่ำเสมอ\n  □ ความยาวใกล้เป้าหมาย (±20%)`;
}

// ── MASTER ─────────────────────────────────────────────────────

export function thMaster(config: BookConfig, architecture: Architecture): string {
  const type = BOOK_TYPES[config.type];
  const codexMaster = codexDigestTh(parseCodex(config.storyBible)); // "" when no codex declared
  let p = `คุณคือนักเขียน${type.label}มืออาชีพ กำลังเขียนหนังสือเรื่อง "${config.title}"

═══ บทบาท & ตัวตน ═══
เขียนหนังสือ ${type.label} ให้สมบูรณ์ทั้งเล่ม เป็น "ภาษาไทย" ทั้งหมด
โทนเสียง: ${config.voice}
กลุ่มผู้อ่านเป้าหมาย: ${config.reader}

═══ ข้อมูลจำเพาะหนังสือ ═══
- ชื่อเรื่อง: ${config.title}
- ประเภท: ${type.label}
- แนวย่อย: ${config.subGenre.replace(/_/g, " ")}
- จำนวนบท: ${config.chapters}
- คำต่อบท (เป้าหมาย): ${config.wordsPerChapter}
- รูปแบบอ้างอิง: ${config.citationStyle}

═══ แก่นเรื่อง / เรื่องย่อ ═══
${config.thesis}

${codexMaster ? codexMaster + "\n" : ""}═══ มาตรฐานคุณภาพ (ยึดเป็นแนวทาง ใช้วิจารณญาณมากกว่ายึดตัวเลขตายตัว) ═══
${thQualityStandards(config.type)}

`;

  if (isFiction(config.type)) {
    p += `═══ หลักการเขียน (นิยาย/เรื่องเล่า) ═══
1. โชว์ ไม่ใช่เล่า — แสดงผ่านการกระทำ ประสาทสัมผัส และบทพูด
2. ทุกฉากต้องมี: ความขัดแย้ง + รายละเอียดประสาทสัมผัส (≥2) + จุดพลิก
3. บทพูดต้องขับเคลื่อนเรื่องหรือเผยตัวละคร ไม่ใช่คำเติม
4. จบบทด้วย hook (คำถาม การเปิดเผย พลิกผัน หรือค้างคา)
5. แต่ละตัวละครมีวิธีพูดเฉพาะตัว แยกออกได้จากน้ำเสียง
6. ความตึงเครียดไต่ระดับขึ้นทั้งเล่ม
7. เลี่ยงสำนวนเฝือ ภาษาฟุ่มเฟือย และคำขยายที่มากเกิน
8. แสดงอารมณ์ผ่านภาษากายและการกระทำ ไม่บอกตรง ๆ

═══ โครงสร้างองก์ ═══
${architecture.parts.map((pp) => `${pp.name}: บท ${pp.chapters[0]}-${pp.chapters[1]} — ${pp.purpose ?? ""}`).join("\n")}
`;
  } else {
    p += `═══ หลักการเขียน (สารคดี/ความรู้) ═══
1. ทุกข้ออ้างต้องมีหลักฐานรองรับ (อ้างอิง สถิติ ตัวอย่าง หรือกรณีศึกษา)
2. ลำดับน้ำหนักหลักฐาน: meta-analysis > RCT > cohort > case > ผู้เชี่ยวชาญ > เรื่องเล่า
3. นิยามศัพท์เฉพาะเมื่อใช้ครั้งแรก
4. เชื่อมเหตุผลระหว่างย่อหน้าให้ชัด (ดังนั้น/อย่างไรก็ตาม/ตัวอย่างเช่น)
5. ข้อโต้แย้งฝ่ายตรงข้าม: นำเสนออย่างเป็นธรรมแล้วโต้กลับด้วยหลักฐาน
6. การสอน: objective → เนื้อหา → แบบฝึกหัด → สรุป → key takeaway
7. มีตัวอย่างและการเปรียบเทียบสำหรับแนวคิดนามธรรมทุกอัน
8. แต่ละบทต้องคืบหน้าการพิสูจน์แก่นเรื่อง

═══ แก่นเรื่อง ═══
${config.thesis}
`;
  }

  p += `
═══ ระบบรักษาความต่อเนื่องอัตโนมัติ (story bible ในแชทเดียว) ═══
คุณดูแลบล็อก STATE เพื่อให้หนังสือสอดคล้องกันโดยไม่ต้องให้ผู้ใช้วางโน้ตซ้ำ
1. ครั้งแรกที่เขียน ให้สร้างบล็อก STATE ที่บันทึก: ตัวละคร (ชื่อ + ลักษณะ/ความสัมพันธ์), ฉาก/กฎของโลก, ข้อเท็จจริงที่ตั้งไว้, เส้นเวลา, ปมที่ยังค้าง และ (นิยาย) ระดับความตึงเครียด
2. ก่อนเขียนทุกบท ให้อ่าน STATE ล่าสุดและคงความสอดคล้อง ห้ามขัดแย้งหรือแนะนำสิ่งที่ตั้งไว้แล้วซ้ำ
3. ท้ายทุกบท ให้แนบบล็อก STATE ที่อัปเดต ครอบด้วยเครื่องหมายนี้เป๊ะ ๆ:

<<<STATE>>>
ตัวละคร: ...
โลก/ข้อเท็จจริง: ...
เส้นเวลา: ...
ปมที่ค้าง: ...
ความตึงเครียด: ...  (เฉพาะนิยาย)
<<<END STATE>>>

เขียน STATE ให้กระชับ (≤ 250 คำ) ข้อเท็จจริงใหม่ขึ้นก่อน เป็นข้อเท็จจริงล้วน ส่งต่อจากบทสู่บท ถ้าผู้ใช้วางบล็อก STATE มาในพรอมป์ตถัดไป ให้ถือเป็นแหล่งความจริง

ตัวอย่างที่กรอกแล้ว (ทำตามรูปแบบนี้ — เนื้อหาเป็นเพียงตัวอย่าง):
<<<STATE>>>
ตัวละคร: อนันต์ — นักสืบ ตอนนี้รู้แล้วว่ากุญแจเปิดโกดัง; ไม่ไว้ใจหมอลี · มาลี — ยังหายตัว พบร่องรอยล่าสุดที่ท่าเรือ
โลก/ข้อเท็จจริง: โกดังอยู่ใต้ท่าที่ 3; แก๊งนัดพบคืนเดือนมืด
เส้นเวลา: คืนที่ 4 หลังการหายตัว
ปมที่ค้าง: ใครส่งรูปถ่ายมา; ทำไมหน้าบัญชีถูกฉีก
ความตึงเครียด: ไต่ขึ้น — ได้รับคำขู่ตรงครั้งแรก
<<<END STATE>>>

⚠ STATE เป็นเครื่องมือทำงาน ไม่ใช่เนื้อหาหนังสือ — ตอนรวมเล่ม/ตีพิมพ์ ต้องลบบล็อก <<<STATE>>> และร่องรอย prompt ทุกชิ้นออกจากต้นฉบับ (ปี 2025 มีนักเขียนหลายรายถูกจับได้เพราะลืม prompt ไว้ในเล่มพิมพ์จริง)

═══ รูปแบบผลลัพธ์ ═══
- เขียนเนื้อหาบทโดยตรง (ไม่มีคำเกริ่น เช่น "นี่คือบท...")
- ขึ้นต้นด้วยชื่อบทเป็นหัวข้อ Markdown (## บทที่ N: ชื่อบท)
- น้ำเสียงสม่ำเสมอ ปรับความยาวให้ใกล้เป้าหมาย (±20%) โดยไม่ยืดเยื้อ
- จบบทด้วย hook หรือบทเชื่อมที่เหมาะกับประเภทบท
- หลังจบบท ให้ output บล็อก <<<STATE>>> ที่อัปเดต (ตามระบบความต่อเนื่อง)
- ผลิตเนื้อหาทั้งหมดเป็นภาษาไทย
`;
  return p;
}

// ── OVERVIEW ───────────────────────────────────────────────────

export function thOverview(config: BookConfig, architecture: Architecture): string {
  let p = `═══ แผนหนังสือ — "${config.title}" ═══\n\n`;
  p += `ส่งพรอมป์ตนี้ครั้งเดียวหลัง Master System Prompt เพื่อวางแผนทั้งเล่มก่อนเขียนบทที่ 1\n\n`;
  p += `ประเภท: ${BOOK_TYPES[config.type].label} · แนวย่อย: ${config.subGenre.replace(/_/g, " ")}\n`;
  p += `แก่นเรื่อง: ${config.thesis}\nผู้อ่าน: ${config.reader}\nโครงสร้าง: ${config.chapters} บท × ~${config.wordsPerChapter} คำ\n\n`;
  p += `═══ ส่วน (Parts) ═══\n`;
  p += architecture.parts.map((pp) => `• ${pp.name} — บท ${pp.chapters[0]}-${pp.chapters[1]}${pp.purpose ? ` — ${pp.purpose}` : ""}`).join("\n");
  p += `\n\n═══ แผนผังบท ═══\n`;
  p += architecture.chapters.map((c) => `บท ${c.number} [${thTypeLabel(c)}] — ${thPurpose(c)}`).join("\n");
  if (config.outline && config.outline.trim()) {
    p += `\n\n═══ โครงเรื่องของผู้เขียน ═══\n${config.outline.trim()}`;
  }
  p += `\n\n═══ เริ่มต้นความต่อเนื่อง ═══\nสร้างบล็อก <<<STATE>>> เริ่มต้น (ตัวละคร, โลก/ข้อเท็จจริง, เส้นเวลา, ปมที่ค้าง${isFiction(config.type) ? ", ความตึงเครียด" : ""}) จากแผนนี้ และดูแลต่อเนื่องทุกบทตามระบบความต่อเนื่อง`;
  p += `\n\nยืนยันว่าเข้าใจแผน แล้ว output บล็อก STATE เริ่มต้น จากนั้นรอพรอมป์ตบทแรก อย่าเพิ่งเขียนบทใด`;
  return p;
}

